/bin/zsh -lc "node --input-type=module <<'JS'
import fs from 'node:fs';
import assert from 'node:assert/strict';
const old = JSON.parse(fs.readFileSync('tmp/notespatial-percussion-before/notespatial-native.nsscore'));
const score = JSON.parse(fs.readFileSync('fedac/native/scores/notespatial-native.nsscore'));
assert.equal(score.dur, old.dur);
assert.deepEqual(score.movements.map(({t0,t1})=>({t0,t1})), old.movements.map(({t0,t1})=>({t0,t1})));
assert.deepEqual(score.fieldShift, old.fieldShift);
let additions=0;
for(let i=0;i<old.lanes.length;i++) {
 const before = new Map();
 for(const e of old.lanes[i].events) {const k=JSON.stringify(e);before.set(k,(before.get(k)||0)+1);}
 for(const e of score.lanes[i].events) {const k=JSON.stringify(e); if(before.get(k)) before.set(k,before.get(k)-1);else {assert.ok(score.lanes[i].name.startsWith('tap ')); additions++;}}
 assert.ok([...before.values()].every(n=>n===0),old.lanes[i].name+' lost an event');
}
const hits = score.lanes.flatMap(l=>l.events.filter(e=>/"'^(tap |kick|snare|hats)/.test(l.name)||e.wave==='"'noise').map(e=>e.t)).sort((a,b)=>a-b);
for(const m of score.movements) {
 const end=m===score.movements.at(-1)?m.t1-3:m.t1;
 const ts=[m.t0,...hits.filter(t=>t>=m.t0&&t<=end),end];
 const gap=Math.max(...ts.slice(1).map((t,i)=>t-ts[i]));
 assert.ok(gap<=1.101,"'`${m.name}: ${gap}s gap`);
 console.log(`${m.name}: longest percussion gap ${gap.toFixed(3)}s`);
}
for(let i=0;i<score.movements.length;i++) {
 const m=score.movements[i];
 const slug=m.name.toLowerCase().replace(/''^[ivx]+ · /,'"'').replace(/["'^a-z]+/g,'"'-').replace(/"'^-|-$/g,'"'');
 const part=JSON.parse(fs.readFileSync("'`fedac/native/scores/notespatial-native-${i+1}-${slug}.nsscore`));
 assert.equal(part.lanes.reduce((n,l)=>n+l.events.length,0),score.lanes.reduce((n,l)=>n+l.events.filter(e=>e.t>=m.t0&&e.t<m.t1).length,0));
}
console.log(`${additions} added percussion events; every original event, cue time and field turn preserved; all 11 chapter exports match.`);
JS' · done

